import json,csv
from pathlib import Path
out=Path('outputs/danya-simulator/assets/buildable-bust-v2')
rows=[('サーボ','ST3215 12V / 30kg·cm',3,11000,'メーカー価格は選択肢により$16.99–21.99。12V版を指定。円額は購入上限枠、確定見積ではない','https://www.waveshare.com/product/modules/st3215-servo.htm'),('USB制御','Bus Servo Adapter (A)',1,1500,'メーカー$4.99。基板最大5A、サーボ3台の同時ストール8.1Aを流せない','https://www.waveshare.com/product/modules/motors-servos/bus-servo-adapter-a.htm'),('鏡','1.1mm厚の表面反射鏡・主鏡＋小鏡',2,5000,'国内特注カット業者を確認。価格、形状公差、反射率・平面度は要見積','https://order-sheetglass.com/det_spm/'),('電源','12V電源・保護回路',1,3000,'12V5A AD-A120P500は税込2380円の候補。3台同時ストール用ではなく制限・遮断設計が必要','https://akizukidenshi.com/catalog/g/g110663/'),('支持・減速','608ZZ、8mm軸、GT2ベルト、カラー',1,3000,'608ZZは6個を仮計上。歯車／プーリーは印刷候補。数量・減速比はトルク検証後','https://www.monotaro.com/p/0825/0243/'),('配線','HDMI・DC・USB・固定具',1,1500,'既存ケーブルを優先。実機端子と曲げ半径で確定',''),('ねじ類','M3/M2、座金、ナット',1,1500,'外装と機構分の上限枠。最終数量未確定',''),('送料等','送料・税・予備枠',1,3500,'見積後に調整。超過する場合は発注しない','')]
assert sum(r[3]for r in rows)==30000
with (out/'BOM-30000.csv').open('w',encoding='utf-8-sig',newline='')as f:w=csv.writer(f);w.writerow(['分類','候補','数量','分類合計の予算上限円','確定状況','出典']);w.writerows(rows)
spec={'status':'SYSTEM DESIGN CANDIDATE / NOT RELEASED FOR PROCUREMENT','budgetCapJPY':30000,'budgetVerified':False,'budgetScope':'Purchased motors, two mirrors, driver, servo supply/protection, transmission/support, fasteners, cables and shipping. Existing projector, existing projector adapter and PC reused. Printing materials not costed.','motor':'Waveshare ST3215 12V','motorQuantity':3,'driver':'Waveshare Bus Servo Adapter (A)','nominalStallTorqueNM':30*.0980665,'continuousTorqueNM':None,'singleStallCurrentA':2.7,'threeMotorStallCurrentA':8.1,'adapterBoardMaxA':5,'rigPivotMM':[35,0,-65],'torsoTranslationMM':[15,0,0],'rigidChestTopZMM':-20,'flexibleCoverRangeZMM':[-20,38],'rangesDeg':{'yaw':45,'pitch':20,'roll':15},'reflectiveMirrorThicknessCandidateMM':1.1,'torsoAlignmentScope':'45 sampled poses against projector hull vertices only. Approx radial screen, not minimum 3D clearance. New screw tabs and all hardware omitted.','transmissionProposal':{'type':'Separate steel support shafts/bearings, servo driving through timing belt; no head weight carried by servo spline alone','ratioCandidate':3,'pulleyTeeth':[20,60],'pitchMM':2,'beltPitchLengthCandidateMM':180,'approxCenterDistanceMM':48.3,'status':'Not yet fit/torque/fastener-qualified'},'sources':[r[5]for r in rows if r[5]]};(out/'system-design-30000.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2))
(out/'SYSTEM_DESIGN_30000.md').write_text('''# Project DANYA：3万円以内の全体設計候補\n\nユーザー指定：スライス作業を保留し、全体機構を優先。承認された小型男性胸像を基準とする。既存プロジェクタ、顔、後頭部を使用。追加凸レンズなし。\n\n## 予算\nBOM-30000.csvの合計上限枠は30,000円。これは見積済み合計ではない。鏡は国内業者が1.1mm表面反射鏡のカットを扱うことを確認した段階で、5,000円で作れる保証はまだない。サーボ3個11,000円、USB制御1,500円、鏡2枚5,000円、電源・保護3,000円、軸受・伝達3,000円、配線1,500円、ねじ1,500円、送料等3,500円。既存PC／プロジェクタとそのアダプターは再利用、印刷材料代は未計上。注文・決済はしていない。\n\n## 駆動を変更\nXM430／U2D2案は予算に合わないため候補から外す。ST3215の12V版3個＋Bus Servo Adapter (A)をPCのUSBから制御する候補へ変更。7.4V版やHS版を混同しない。3kgではなく30kg·cm（約2.94Nm）はストールトルクで、連続許容トルクとして使わない。連続トルクは未確認。\n\n荷重経路：底板 → 2個の軸受で支えるヨー軸 → 左右のピッチ支持部 → ロール支持部 → 一体の光学フレーム。頭とプロジェクタの重量は8mm軸と608ZZ軸受へ流し、サーボはベルト経由で回す。20歯／60歯の3:1減速、2mmピッチ・180mmベルトなら中心距離は概算48.3mm。軸の間に光路を通し、横断するシャフトは置かず左右の短い軸で支持する。歯数・ベルト長・軸の締結は配置とトルクの検証後に確定する。\n\n## 一体で動く光学フレーム\n頭・主鏡・小鏡・プロジェクタを同じ剛体として動かし、相互位置を保持する。現行投影位置と元の頭の形を保つ。外装形状は拡大せず前方へ15mm移す候補、回転中心は[35,0,-65]mm。サンプル45姿勢・実寸プロジェクタ凸包で最悪の半径方向余裕は約9.37mm。ただし3D最短距離でも連続動作合格でもない。鏡・駆動部・配線は別途検証が必要。\n\n## 硬い首は廃止して柔軟なカバーへ\n現在の硬い襟は頭に干渉する。胸の剛体部分をZ=-20mm以下、上部Z=-20〜38mmを柔軟カバーとする候補。新回転中心で頭・顔全頂点を検査すると、左右±45°／ピッチ±20°／ロール±15°全域で最低Zは保守的に-11.565mm以上。したがってZ=-20mm以下の硬い胸部と頭・顔は上下方向に8.435mm以上離れる。これは柔軟カバーの変形や内部の梁を保証するものではない。柔軟カバーは荷重を受けない。\n\n## 鏡\n主鏡は約129.846×155.403mmの予定有効領域。1.1mm厚の表面反射鏡は、反射面の位置を変えずにモデル上で頭内壁まで約0.829mm、顔まで約17.694mm。これは名目面間距離のみ。厚み公差、輪郭加工、フレーム保持、位置調整余裕を入れた合格ではない。裏面3点支持と押さえを検討し、表面反射面を光側へ向ける。普通の裏面反射鏡へ置き換えない。小鏡は約23.828×35.185mmの有効領域。DXFは光学領域で切断線ではない。\n\n## 配線・電源\n既存プロジェクタの電源系と12Vサーボ系は分離。PCからHDMIで映像、USBでサーボ制御。背面に固定のサービスパネルを置き、内部は抜き差し用余白とストレインリリーフ、3軸をまたぐたるみを設ける。コネクタ穴は型番未確定のためまだ開けない。\n\nST3215のストール2.7A×3=8.1Aに対しUSB基板の上限は5A。5Aアダプターをつなぐだけで完成とはしない。給電分配・電流制限・ヒューズ・異常停止時の保持を設計する。予算内で保護を確定できない場合は電源構成を再選定する。\n\n## 次に解く事項\n- 新中心で全機構を収める支持フレーム、3軸サーボ・減速機・軸受の干渉と工具アクセス。\n- 既存投影面の全顔照射、光束の太さ、ピント、主鏡輪郭の製作余裕。\n- 可動部の実重量・重心・重力補償、連続通電温度。重量不明のままストール値で合格させない。\n- 実際の鏡見積と送料・税を入れて3万円以内に確定する。\n\n## 主要出典\n- https://www.waveshare.com/product/modules/st3215-servo.htm\n- https://files.waveshare.com/upload/5/59/ST3215-3D.zip （正式CAD取得済み）\n- https://docs.waveshare.com/Bus_Servo_Adapter_A/FAQ （最大5A）\n- https://order-sheetglass.com/det_spm/ （1.1mm／2mm表面反射鏡の特注カット）\n- https://www.monotaro.com/p/0825/0243/ （NSK608ZZ候補）\n- https://akizukidenshi.com/catalog/r/r12v （12V電源価格）\n''')
